struct key *construct_key_and_link(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *target_keyring = NULL;
    struct user_struct *user = NULL;
    int ret;

    if (!dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    target_keyring = keyring_search(ctx, dest_keyring, NULL, 0);
    if (IS_ERR(target_keyring)) {
        return target_keyring;
    }

    user = get_current_user();
    if (!user) {
        ret = -ENOMEM;
        goto error;
    }

    key = alloc_key(callout_info, callout_len, user);
    if (IS_ERR(key)) {
        ret = PTR_ERR(key);
        goto error;
    }

    ret = construct_key(key, aux, callout_info, callout_len, flags);
    if (ret < 0) {
        key_put(key);
        return ERR_PTR(ret);
    }

    ret = key_link(key, target_keyring);
    if (ret < 0) {
        key_put(key);
        return ERR_PTR(ret);
    }

    return key;

error:
    if (target_keyring)
        key_put(target_keyring);
    if (user)
        free_user(user);
    return ERR_PTR(ret);
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct user_struct *user = NULL;
    int ret;

    if (!dest_keyring || key_put(dest_keyring, "keyring")) {
        return ERR_PTR(-EINVAL);
    }

    user = get_current_user();
    if (!user) {
        return ERR_PTR(-ENOMEM);
    }

    key = key_alloc(&key_type_user, NULL, current_cred(), NULL, flags, 0, NULL);
    if (IS_ERR(key)) {
        ret = PTR_ERR(key);
        put_user(user);
        return key;
    }

    key->uid = current_uid();
    key->gid = current_gid();
    key->perm = KEY_POS_ALL & ~KEY_POS_SETATTR |
                KEY_USR_ALL & ~KEY_USR_VIEW | ~KEY_USR_READ |
                KEY_INTERNALLY_PERSISTENT;

    if (callout_len) {
        key->description = kstrndup(callout_info, callout_len, GFP_KERNEL);
        if (!key->description) {
            key_put(key);
            put_user(user);
            return ERR_PTR(-ENOMEM);
        }
    }

    ret = key_instantiate(key, aux, 0);
    if (ret < 0) {
        key_put(key);
        put_user(user);
        return ERR_PTR(ret);
    }

    ret = key_link(key, dest_keyring);
    if (ret < 0) {
        key_put(key);
        put_user(user);
        return ERR_PTR(ret);
    }

    put_user(user);
    return key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct user_struct *user = NULL;
    int ret;

    /* Check the type of index key */
    if (!ctx || !ctx->index_key.type) {
        return ERR_PTR(-EINVAL);
    }

    /* Retrieve the user */
    user = get_current_user();
    if (!user) {
        return ERR_PTR(-ENOMEM);
    }

    /* Allocate a new key */
    key = key_alloc(ctx->index_key.type, &ctx->index_key, sizeof(ctx->index_key), user,
                    current_cred(), flags, NULL);
    if (IS_ERR(key)) {
        put_user(user);
        return key;
    }

    /* Set callout info */
    ret = key_instantiate_and_link(key, callout_info, callout_len, dest_keyring, aux);
    if (ret < 0) {
        key_revoke(key);
        key_put(key);
        put_user(user);
        return ERR_PTR(ret);
    }

    put_user(user);
    return key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key = NULL;
    struct key *dest_keyring_ref = NULL;
    struct user_struct *user = NULL;
    int ret;

    if (!ctx || !callout_info || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    dest_keyring_ref = key_get(dest_keyring);
    if (!dest_keyring_ref) {
        return ERR_PTR(-ENOKEY);
    }

    user = get_current_user();
    if (!user) {
        key_put(dest_keyring_ref);
        return ERR_PTR(-ENOMEM);
    }

    key = key_alloc(&key_type_user, NULL, current_fsuid(), current_fsgid(),
                    user, 0, flags, NULL);
    if (IS_ERR(key)) {
        put_user(user);
        key_put(dest_keyring_ref);
        return key;
    }

    ret = key_instantiate_and_link(key, callout_info, callout_len, dest_keyring_ref, NULL);
    if (ret < 0) {
        key_revoke(key);
        key_put(key);
        put_user(user);
        key_put(dest_keyring_ref);
        return ERR_PTR(ret);
    }

    put_user(user);
    key_put(dest_keyring_ref);
    return key;
}

struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *new_key = NULL;
    struct key *index_key = NULL;
    struct key_user *user;
    int ret;

    if (!ctx || !callout_info || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    index_key = lookup_user_index_key(ctx);
    if (IS_ERR(index_key)) {
        return index_key;
    }

    user = lookup_key_user(current_fsuid());
    if (IS_ERR(user)) {
        new_key = ERR_CAST(user);
        goto out_put_index_key;
    }

    new_key = alloc_key();
    if (!new_key) {
        new_key = ERR_PTR(-ENOMEM);
        goto out_put_user;
    }

    ret = construct_key(new_key, index_key, callout_info, callout_len, aux, flags);
    if (ret < 0) {
        new_key = ERR_PTR(ret);
        goto out_free_key;
    }

    ret = link_key(new_key, dest_keyring);
    if (ret < 0) {
        new_key = ERR_PTR(ret);
        goto out_free_key;
    }

    key_get(new_key);

    goto out_put_user;

out_free_key:
    free_key(new_key);
out_put_user:
    put_user(user);
out_put_index_key:
    key_put(index_key);
    return new_key;
}
